:root {
  color-scheme: light;
  accent-color: #2f5bd3;
  --bg: #f5f6f8;
  --surface: #ffffff;
  --text: #1f2430;
  --muted: #5b6472;
  --line: #e3e6ec;
  --line-strong: #8a93a3;
  --accent: #2f5bd3;
  --accent-strong: #234aad;
  --danger: #b42318;
  --radius: 6px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

::selection {
  background: #cfdbf8;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.app-header {
  padding: 16px 24px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}

.app-header h1 {
  margin: 0;
  font-size: 1.25rem;
}

.layout {
  display: grid;
  gap: 24px;
  max-width: 1100px;
  margin: 0 auto;
  padding: 24px;
}

@media (min-width: 800px) {
  .layout {
    grid-template-columns: minmax(260px, 320px) minmax(0, 1fr);
    align-items: start;
  }
}

.panel {
  padding: 16px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.panel h2 {
  margin: 0 0 12px;
  font-size: 1rem;
}

.list-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.muted {
  color: var(--muted);
  font-size: 0.9rem;
}

.field {
  margin-bottom: 12px;
}

.field label {
  display: block;
  margin-bottom: 4px;
  font-size: 0.9rem;
  font-weight: 600;
}

input {
  width: 100%;
  min-height: 44px;
  padding: 8px 10px;
  font: inherit;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
}

input[aria-invalid="true"] {
  border-color: var(--danger);
}

.field-error {
  min-height: 1.25rem;
  margin: 4px 0 0;
  font-size: 0.875rem;
  color: var(--danger);
}

.form-actions {
  display: flex;
  gap: 8px;
}

.btn {
  min-height: 44px;
  padding: 8px 14px;
  font: inherit;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
}

.btn:hover:not(:disabled) {
  border-color: var(--text);
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.btn-primary {
  color: #ffffff;
  background: var(--accent);
  border-color: var(--accent);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.btn-danger {
  color: var(--danger);
}

.btn-danger:hover:not(:disabled) {
  border-color: var(--danger);
}

.status {
  min-height: 1.5rem;
  margin: 0 0 8px;
  font-size: 0.9rem;
  color: var(--muted);
}

.status-error {
  color: var(--danger);
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  padding: 10px 8px;
  text-align: left;
  vertical-align: middle;
  border-bottom: 1px solid var(--line);
}

th {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--muted);
}

.num {
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.actions {
  text-align: right;
  white-space: nowrap;
}

.actions .btn {
  min-height: 40px;
  margin-left: 6px;
  padding: 4px 10px;
  font-size: 0.9rem;
}

.empty {
  padding: 24px 8px;
  text-align: center;
  color: var(--muted);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .btn {
    transition: none;
  }
}

