  margin-bottom: 12px;
}

.field label {
  display: block;
  margin-bottom: 4px;
  font-size: 0.9rem;
  font-weight: 600;
}

input {
  width: 100%;
  min-height: 44px;
  padding: 8px 10px;
  font: inherit;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
}

input[aria-invalid="true"] {
  border-color: var(--danger);
}

.field-error {
  min-height: 1.25rem;
  margin: 4px 0 0;
  font-size: 0.875rem;
  color: var(--danger);
}

.form-actions {
  display: flex;
  gap: 8px;
}

.btn {
  min-height: 44px;
  padding: 8px 14px;
  font: inherit;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
}

.btn:hover:not(:disabled) {
  border-color: var(--text);
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.btn-primary {
  color: #ffffff;
  background: var(--accent);
  border-color: var(--accent);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.btn-danger {
  color: var(--danger);
}

.btn-danger:hover:not(:disabled) {
  border-color: var(--danger);
}

.status {
  min-height: 1.5rem;
  margin: 0 0 8px;
  font-size: 0.9rem;
  color: var(--muted);
}

.status-error {
  color: var(--danger);
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  padding: 10px 8px;
  text-align: left;
  vertical-align: middle;
  border-bottom: 1px solid var(--line);
}

th {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--muted);
}

.num {
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.actions {
  text-align: right;
  white-space: nowrap;
}

.actions .btn {
  min-height: 40px;
  margin-left: 6px;
  padding: 4px 10px;
  font-size: 0.9rem;
}

.empty {
  padding: 24px 8px;
  text-align: center;
  color: var(--muted);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .btn {
    transition: none;
  }
}
